/projects/{projectId}/servers/{serverId}/doctor {"$ref": "#/components/requestBodies/emptyBody"}
/projects/{projectId}/servers/{serverId} {"required": true, "content": {"application/json": {"schema": {"$ref": "#/components/schemas/ProjectServerUpdateRequest"}, "example": {"enabled": false}}}}
/projects/{projectId}/servers/{serverId}/conformance-runs {"required": false, "content": {"application/json": {"schema": {"type": "object", "additionalProperties": false, "properties": {"suites": {"type": "array", "minItems": 1, "items": {"type": "string", "enum": ["protocol", "apps", "tasks"]}, "description": "Suites to run. Defaults to protocol, apps, and tasks. OAuth is not available on this surface."}, "idempotencyKey": {"type": "string", "maxLength": 200, "description": "Deduplicates a retried POST for the same saved server. Mapped to a namespaced externalRunId (`api:<projectId>:<serverId>:<key>`); a keyless start always inserts and spends quota."}, "protocolVersion": {"type": "string", "enum": ["2025-03-26", "2025-06-18", "2025-11-25", "2026-07-28"], "description": "Pin one MCP protocol version. Without it the run uses the version the server negotiates."}, "engineVersion": {"type": "string"}, "settings": {"type": "string", "enum": ["saved", "none"], "description": "`saved` (the default) runs the server's saved conformance settings. `none` runs every check with no tool inputs."}}}}}}
/projects/{projectId}/eval-runs {"required": true, "content": {"application/json": {"schema": {"$ref": "#/components/schemas/EvalRunCreateRequest"}, "example": {"suiteName": "smoke", "serverIds": ["srv_abc123"], "tests": [{"title": "echo works", "runs": 1, "model": "anthropic/claude-haiku-4.5", "provider": "anthropic", "steps": [{"id": "s1", "kind": "prompt", "prompt": "Use the echo tool to say hi"}, {"id": "s2", "kind": "assert", "assertion": {"type": "toolCalledWith", "toolName": "echo", "args": {"args": {"text": "hi"}}}}]}]}}}}
